### Description

The SDK logger drops group attributes such as those shown in this testcase.

```go
package bug

import (
	"log/slog"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/posit-dev/launcher-go-sdk/logger"
)

// jobDetails implements slog.LogValuer, the recommended Go pattern for
// attaching structured log fields from a type.
type jobDetails struct {
	ID   string
	User string
}

func (j jobDetails) LogValue() slog.Value {
	return slog.GroupValue(
		slog.String("id", j.ID),
		slog.String("user", j.User),
	)
}

// TestLoggerDropsStructuredFields demonstrates that the launcher SDK logger
// drops slog.Group attributes and slog.LogValuer values that resolve to a
// group. Callers lose structured fields with no indication of a problem.
func TestLoggerDropsStructuredFields(t *testing.T) {
	dir := t.TempDir()
	lgr, err := logger.NewLogger("test", false, dir)
	if err != nil {
		t.Fatal(err)
	}

	// Case 0: simple scalar attributes — these work correctly.
	lgr.Warn("operation failed", "id", "11", "user", "alice")

	// Case 1: slog.Group — the canonical way to group related fields.
	lgr.Warn("operation failed",
		slog.Group("job",
			slog.String("id", "42"),
			slog.String("user", "bob"),
		))

	// Case 2: slog.LogValuer returning a group — the recommended pattern for
	// attaching structured logging to a type. Value.Resolve() calls LogValue(),
	// which returns KindGroup, which formatAttr then discards.
	job := jobDetails{ID: "99", User: "carmen"}
	lgr.Warn("operation failed", "job", job)

	output, err := os.ReadFile(filepath.Join(dir, "test.log"))
	if err != nil {
		t.Fatal(err)
	}
	t.Logf("captured output:\n%s", output)

	// Case 0: scalars must appear.
	for _, want := range []string{"11", "alice"} {
		if !strings.Contains(string(output), want) {
			t.Errorf("scalar field %q is missing from log output", want)
		}
	}
	// Cases 1 and 2: grouped fields are silently dropped.
	for _, want := range []string{"42", "bob", "99", "carmen"} {
		if !strings.Contains(string(output), want) {
			t.Errorf("field %q is missing from log output (silently dropped)", want)
		}
	}
}
```

